const rfq = $input.first().json;

const errors = [];
const reviewFlags = [];

const requiredFields = [
  'rfq_id',
  'customer_name',
  'product_id',
  'requested_quantity',
  'spot_material_surcharge_pct',
  'requested_delivery_date',
  'requested_discount_pct',
  'sales_rep',
  'request_channel',
];

const allowedFields = new Set(requiredFields);

for (const field of requiredFields) {
  if (!(field in rfq) || rfq[field] === null || rfq[field] === '') {
    errors.push(`MISSING_OR_NULL:${field}`);
  }
}

for (const field of Object.keys(rfq)) {
  if (!allowedFields.has(field)) {
    errors.push(`UNEXPECTED_FIELD:${field}`);
  }
}

if (typeof rfq.rfq_id !== 'string' || !/^RFQ-\d{4}-\d{5}$/.test(rfq.rfq_id)) {
  errors.push('INVALID_RFQ_ID');
}

if (
  typeof rfq.customer_name !== 'string' ||
  rfq.customer_name.length < 1 ||
  rfq.customer_name.length > 120
) {
  errors.push('INVALID_CUSTOMER_NAME');
}

if (
  typeof rfq.product_id !== 'string' ||
  !/^[A-Z0-9-]{3,40}$/.test(rfq.product_id)
) {
  errors.push('INVALID_PRODUCT_ID');
}

if (
  !Number.isInteger(rfq.requested_quantity) ||
  rfq.requested_quantity < 1 ||
  rfq.requested_quantity > 100000
) {
  errors.push('INVALID_REQUESTED_QUANTITY');
}

if (
  typeof rfq.spot_material_surcharge_pct !== 'number' ||
  rfq.spot_material_surcharge_pct < -0.05 ||
  rfq.spot_material_surcharge_pct > 0.15
) {
  errors.push('INVALID_SURCHARGE_PCT');
}

if (
  typeof rfq.requested_discount_pct !== 'number' ||
  rfq.requested_discount_pct < 0 ||
  rfq.requested_discount_pct > 0.3
) {
  errors.push('INVALID_DISCOUNT_PCT');
}

if (
  typeof rfq.sales_rep !== 'string' ||
  rfq.sales_rep.length < 1 ||
  rfq.sales_rep.length > 120
) {
  errors.push('INVALID_SALES_REP');
}

if (!['webhook', 'manual_test'].includes(rfq.request_channel)) {
  errors.push('INVALID_REQUEST_CHANNEL');
}

const datePattern = /^\d{4}-\d{2}-\d{2}$/;
const requestedDate = new Date(`${rfq.requested_delivery_date}T00:00:00Z`);
const today = new Date();
today.setUTCHours(0, 0, 0, 0);

if (
  typeof rfq.requested_delivery_date !== 'string' ||
  !datePattern.test(rfq.requested_delivery_date) ||
  Number.isNaN(requestedDate.getTime()) ||
  requestedDate <= today
) {
  errors.push('INVALID_OR_PAST_DELIVERY_DATE');
}

if (rfq.requested_quantity > 500) {
  reviewFlags.push('REVIEW_REQUIRED_HIGH_QUANTITY');
}

if (rfq.requested_discount_pct > 0) {
  reviewFlags.push('REVIEW_REQUIRED_DISCOUNT');
}

const validationStatus =
  errors.length > 0
    ? 'FAILED_CLOSED'
    : 'VALIDATED_PENDING_MASTER_LOOKUP';

return [
  {
    json: {
      ...rfq,
      input_data_classification: 'L1',
      validation_version: 'rfq-schema-v1',
      validation_status: validationStatus,
      validation_errors: errors,
      review_flags: reviewFlags,
      product_lookup_status:
        errors.length > 0 ? 'NOT_STARTED' : 'PENDING_MASTER_LOOKUP',
    },
  },
];

const rfq = $('Validate RFQ (Deterministic)').first().json;
const product = $json;

const round2 = (value) =>
  Math.round((value + Number.EPSILON) * 100) / 100;

const quantity = Number(rfq.requested_quantity);
const surcharge = Number(rfq.spot_material_surcharge_pct);
const targetMargin = Number(product.cfo_target_gross_margin_pct);
const proposedPrice = Number(rfq.proposed_quote_price_usd);

const materialCost = round2(
  Number(product.raw_material_cost_usd) * (1 + surcharge)
);

const laborCost = round2(
  Number(product.estimated_labor_hours) *
  Number(product.labor_rate_hourly_usd)
);

const unitCost = round2(materialCost + laborCost);
const totalCost = round2(unitCost * quantity);
const minimumCfoPrice = round2(
  totalCost / (1 - targetMargin)
);

const realizedMargin = round2(
  (proposedPrice - totalCost) / proposedPrice
);

const isMarginCompliant =
  proposedPrice >= minimumCfoPrice &&
  realizedMargin >= targetMargin;

return {
  json: {
    ...rfq,
    ...product,
    material_cost_usd: materialCost,
    labor_cost_usd: laborCost,
    unit_cost_usd: unitCost,
    total_cost_usd: totalCost,
    minimum_cfo_approved_price_usd: minimumCfoPrice,
    proposed_quote_price_usd: proposedPrice,
    realized_gross_margin_pct: realizedMargin,
    is_margin_compliant: isMarginCompliant,
    decision_code: isMarginCompliant
      ? "APPROVAL_CANDIDATE_PENDING_HUMAN"
      : "REVIEW_REQUIRED",
    calculation_version: "phase2-calc-v1"
  }
};

const quote = $json;

return {
  json: {
    ...quote,
    ai_status: "MOCK_NO_LLM_CALL",
    prompt_version: "phase2-explanation-v1",
    customer_explanation:
      "この見積は、製品原価、材料サーチャージ、労務費、数量、およびCFO最低価格ルールに基づいて算出されています。",
    internal_rationale:
      "価格と粗利率は決定論的コードで計算され、CFO最低価格以上であることを確認済みです。",
    negotiation_options: [],
    exception_reason: null,
    loop_count: 0,
    loop_stop_reason: "NO_LLM_CALL"
  }
};

const q = $json;

const round2 = (value) =>
  Math.round((value + Number.EPSILON) * 100) / 100;

const materialCost = round2(
  Number(q.raw_material_cost_usd) *
  (1 + Number(q.spot_material_surcharge_pct))
);

const laborCost = round2(
  Number(q.estimated_labor_hours) *
  Number(q.labor_rate_hourly_usd)
);

const unitCost = round2(materialCost + laborCost);
const totalCost = round2(
  unitCost * Number(q.requested_quantity)
);

const minimumCfoPrice = round2(
  totalCost / (1 - Number(q.cfo_target_gross_margin_pct))
);

const numericCheck =
  Math.abs(Number(q.material_cost_usd) - materialCost) < 0.01 &&
  Math.abs(Number(q.labor_cost_usd) - laborCost) < 0.01 &&
  Math.abs(Number(q.unit_cost_usd) - unitCost) < 0.01 &&
  Math.abs(Number(q.total_cost_usd) - totalCost) < 0.01 &&
  Math.abs(
    Number(q.minimum_cfo_approved_price_usd) - minimumCfoPrice
  ) < 0.01;

const policyCheck =
  Number(q.proposed_quote_price_usd) >= minimumCfoPrice &&
  Number(q.realized_gross_margin_pct) >=
    Number(q.cfo_target_gross_margin_pct);

const passed = numericCheck && policyCheck;

return {
  json: {
    ...q,
    ai_numeric_revalidation_status: passed ? "PASSED" : "FAILED",
    ai_revalidation_version: "phase2-revalidation-v1",
    decision_code: passed
      ? q.decision_code
      : "REVIEW_REQUIRED_AI_REVALIDATION_FAILED"
  }
};

return {
  json: {
    ...$json,
    human_approval_status: "NOT_ELIGIBLE",
    human_decision: null,
    human_approval_required: true,
    execution_blocked_until_human_approval: true,
    stop_reason: "CFO_POLICY_FAILED",
    decision_code: "REVIEW_REQUIRED"
  }
};

return {
  json: {
    ...$json,
    human_approval_status: "NOT_ELIGIBLE",
    human_decision: null,
    human_approval_required: true,
    execution_blocked_until_human_approval: true,
    stop_reason: "AI_NUMERIC_REVALIDATION_FAILED",
    decision_code: "REVIEW_REQUIRED_AI_REVALIDATION_FAILED"
  }
};

return {
  json: {
    ...$json,
    human_approval_status: "PENDING",
    human_decision: null,
    human_approval_required: true,
    execution_blocked_until_human_approval: true,
    approval_rejection_reason: null
  }
};

const quote = $json;

return {
  json: {
    ...quote,
    trace_id:
      `${quote.rfq_id}:${quote.calculation_version}`,
    workflow_execution_id: $execution.id,
    audit_event_type: "HUMAN_APPROVAL_PENDING",
    audit_status: "PENDING",
    audit_actor_id: null,
    audit_decision: null,
    audit_reason:
      "Deterministic calculation and AI post-validation passed. Explicit human approval is required.",
    audit_created_at: new Date().toISOString()
  }
};

const q = $json;

const approvalPayload = {
  rfq_id: q.rfq_id,
  trace_id: q.trace_id,
  calculation_version: q.calculation_version,
  prompt_version: q.prompt_version,
  proposed_quote_price_usd: q.proposed_quote_price_usd,
  minimum_cfo_approved_price_usd:
    q.minimum_cfo_approved_price_usd,
  realized_gross_margin_pct:
    q.realized_gross_margin_pct,
  cfo_target_gross_margin_pct:
    q.cfo_target_gross_margin_pct,
  decision_code: q.decision_code
};

const createdAt = new Date();
const expiresAt = new Date(
  createdAt.getTime() + 24 * 60 * 60 * 1000
);

return {
  json: {
    ...q,
    approval_payload_json: JSON.stringify(approvalPayload),
    approval_created_at: createdAt.toISOString(),
    approval_expires_at: expiresAt.toISOString()
  }
};

